const chat = $env.ADMIN_TELEGRAM_CHAT_ID;
if (!chat) return [];  // sin chat de administrador configurado: solo queda en el historial de n8n
const e = $input.first().json;
// Nunca reenviar el token del bot: algunas fallas incluyen la URL completa de Telegram.
const clean = s => String(s ?? '').replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').slice(0, 600);
const esc = s => clean(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = [
  '🚨 <b>Falla en CyberManagement</b>',
  `<b>Workflow:</b> ${esc(e.workflow?.name)}`,
  `<b>Paso:</b> ${esc(e.execution?.lastNodeExecuted)}`,
  `<b>Error:</b> ${esc(e.execution?.error?.message)}`,
  `<b>Ejecución:</b> ${esc(e.execution?.id)}`,
].join('\n');
return [{ json: { chat_id: chat, text, parse_mode: 'HTML' } }];
